namespace Challenge;public sealed class CouponStore{public HashSet<string> Valid=new();public HashSet<string> Used=new();public List<string> Audit=new();internal object Gate=new();}public sealed class CouponService(CouponStore store){public bool Redeem(string code){lock(store.Gate){if(!store.Valid.Contains(code)||!store.Used.Add(code))return false;store.Audit.Add(code);return true;}}}
